const raw = $json.candidates[0].content.parts[0].text.replace(/^```json\n?|```$/g, '').trim();
const parsed = JSON.parse(raw);
if (!Array.isArray(parsed.questions) || parsed.questions.length < 5) throw new Error('quiz_schema_invalid: questions count');
for (const q of parsed.questions) {
  if (!Array.isArray(q.options) || q.options.length !== 4) throw new Error('quiz_schema_invalid: options');
  if (typeof q.correctIndex !== 'number' || q.correctIndex < 0 || q.correctIndex > 3) throw new Error('quiz_schema_invalid: correctIndex');
}
const ctx = $('Pick niche + jobId').first().json;
return [{ json: { ...ctx, title: parsed.title, questions: parsed.questions.map((q, i) => ({ id: i + 1, ...q })) } }];

const data = $('Parse + validate').first().json;
const tasks = [];
for (const q of data.questions) {
  tasks.push({ jobId: data.jobId, questionId: q.id, kind: 'question', text: q.question, voice: 'vi-VN-HoaiMyNeural' });
  tasks.push({ jobId: data.jobId, questionId: q.id, kind: 'reveal', text: `Đáp án đúng là ${String.fromCharCode(65 + q.correctIndex)}: ${q.options[q.correctIndex]}`, voice: 'vi-VN-NamMinhNeural' });
}
return tasks.map(t => ({ json: t }));

const tasks = $('Build TTS tasks').all().map(i => i.json);
const results = $('Edge TTS').all().map(i => i.json);
const data = $('Parse + validate').first().json;
const byQ = new Map();
for (let i = 0; i < tasks.length; i++) {
  const t = tasks[i];
  const r = results[i];
  const entry = byQ.get(t.questionId) || {};
  if (t.kind === 'question') entry.questionAudioPath = r.audioPath;
  if (t.kind === 'reveal') entry.revealAudioPath = r.audioPath;
  byQ.set(t.questionId, entry);
}
const questions = data.questions.map(q => ({ ...q, ...(byQ.get(q.id) || {}) }));
return [{ json: { jobId: data.jobId, niche: data.niche, props: { title: data.title, channelName: 'videofarm', variant: new Date().getDate() % 2 === 0 ? 'dark' : 'light', questions } } }];
